.ws-bank-label{font-size:12px;font-weight:800;color:#7C3AED;text-transform:uppercase;letter-spacing:.4px;}
.ws-td{height:26px;}
.ws-bank{gap:6px;padding:0;}
.ws-bank .wb-chip{font-size:13px;padding:3px 10px;}

