 color:#1a1a1a;background:#ffffff;}
.wb-topbar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;}
.wb-patbadge{display:inline-flex;align-items:center;gap:6px;background:#1a1a2e;color:#fff;
 font-weight:800;font-size:13px;letter-spacing:.5px;text-transform:uppercase;
 padding:5px 12px;border-radius:20px;}
.wb-stagebadge{display:inline-flex;align-items:center;gap:7px;background:#4755691A;
 border:2px solid #475569;color:#475569;font-weight:800;font-size:13px;
 padding:4px 12px;border-radius:20px;}
.wb-stagebadge2{display:inline-flex;align-items:center;gap:7px;font-weight:800;font-size:12.5px;
 padding:3px 10px;border-radius:16px;}
.wb-progress{display:flex;gap:5px;margin-top:2px;}
.wb-dot{flex:1;height:7px;border-radius:4px;background:#E5E7EB;}
.wb-pagetitle{font-size:24px;font-weight:800;color:#1a1a2e;border-bottom:3px solid #475569;
 padding-bottom:6px;margin:2px 0 0;}
.wb-para{font-size:15.5px;line-height:1.55;font-weight:500;color:#1a1a1a;margin:0;}
.wb-body{flex:1;display:flex;flex-direction:column;gap:10px;}
.wb-chiplist{display:flex;flex-wrap:wrap;gap:8px;}
.wb-chip{background:#47556914;border:1.5px solid #47556955;color:#1a1a1a;
 font-weight:700;font-size:14px;padding:6px 12px;border-radius:9px;}
.wb-table{border-collapse:collapse;font-size:14.5px;width:100%;}
.wb-table td{padding:6px 8px;border-bottom:1px solid #E5E7EB;vertical-align:top;}
.wb-word{font-weight:800;color:#475569;white-space:nowrap;}
.wb-bullets{margin:0;padding-left:20px;font-size:15px;line-height:1.7;}
.wb-bullets li{margin-bottom:3px;}
.wb-blank{color:#475569;font-weight:700;}
.wb-footer{display:flex;justify-content:space-between;font-size:11.5px;color:#6B7280;
 border-top:1px solid #E5E7EB;padding-top:6px;}
.wb-hint{font-size:13px;color:#6B7280;font-style:italic;}
.wb-fullline{width:100%;border-bottom:2px solid #9CA3AF;height:22px;box-sizing:border-box;}

